func loadPrivateKey(path string) (*rsa.PrivateKey, error) {
	pemData, err := ioutil.ReadFile(path)
	if err != nil {
		return nil, err
	}

	block, _ := pem.Decode(pemData)
	if block == nil || block.Type != "PRIVATE KEY" {
		return nil, fmt.Errorf("failed to parse private key")
	}

	// 使用 ParsePKCS8PrivateKey 解析 PKCS#8 格式的私钥
	privateKeyInterface, err := x509.ParsePKCS8PrivateKey(block.Bytes)
	if err != nil {
		return nil, err
	}

	privateKey, ok := privateKeyInterface.(*rsa.PrivateKey)
	if !ok {
		return nil, fmt.Errorf("not an RSA private key")
	}

	return privateKey, nil
}

// 加载公钥
func loadPublicKey(path string) (*rsa.PublicKey, error) {
	pemData, err := ioutil.ReadFile(path)
	if err != nil {
		return nil, err
	}
	block, _ := pem.Decode(pemData)
	if block == nil || block.Type != "PUBLIC KEY" {
		return nil, fmt.Errorf("failed to parse public key")
	}

	// 解析公钥并进行类型断言
	pubKeyInterface, err := x509.ParsePKIXPublicKey(block.Bytes)
	if err != nil {
		return nil, err
	}

	pubKey, ok := pubKeyInterface.(*rsa.PublicKey)
	if !ok {
		return nil, fmt.Errorf("not an RSA public key")
	}

	return pubKey, nil
}

// 安装 golang-jwt/jwt 库
// go get github.com/golang-jwt/jwt/v4

func generateJWT(w http.ResponseWriter, r *http.Request) {
	privateKey, err := loadPrivateKey("/private.pem")
	if err != nil {
		log.Fatalf("Unable to load private key: %v", err)
	}

	m := make(map[string]interface{})
	if err := json.NewDecoder(r.Body).Decode(&m); err != nil {
		http.Error(w, "could not decode request", http.StatusBadRequest)
		return
	}

	token := jwt.NewWithClaims(jwt.SigningMethodRS256, jwt.MapClaims{
		"iss":    "https://kubernetes.default.svc.cluster.local", // Issuer
		"sub":    m["username"],                                  // Subject
		"aud":    "https://kubernetes.default.svc.cluster.local", // Audience
		"exp":    time.Now().Add(time.Hour * 24).Unix(),          // Expiration Time
		"iat":    time.Now().Unix(),                              // Issued At
		"nbf":    time.Now().Unix(),                              // Not Before
		"groups": m["groups"],
	})

	log.Println("m[\"groups\"]:", m["groups"])
	log.Println("m[\"username\"]", m["username"])

	tokenString, err := token.SignedString(privateKey)
	if err != nil {
		log.Println("token.SignedString(secretKey) error")
		w.WriteHeader(http.StatusBadRequest)
		return
	}

	w.WriteHeader(http.StatusOK)
	_, _ = w.Write([]byte(tokenString))

}

func healthzHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}
	log.Println("Healthz check passed")
	w.WriteHeader(http.StatusOK)
	_, _ = w.Write([]byte("ok"))
}

func readyzHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}
	// 在这里可以添加更复杂的就绪逻辑，比如检查依赖服务
	log.Println("Readiness check passed")
	w.WriteHeader(http.StatusOK)
	_, _ = w.Write([]byte("ok"))
}

func decodeJWT(tokenString string) (interface{}, error) {
	publicKey, err := loadPublicKey("public.pem")
	if err != nil {
		log.Fatalf("Unable to load public key: %v", err)
	}

	token, err := jwt.Parse(tokenString, func(token *jwt.Token) (interface{}, error) {
		// 确保使用的是 RS256 签名方法
		if _, ok := token.Method.(*jwt.SigningMethodRSA); !ok {
			return nil, fmt.Errorf("unexpected signing method: %v", token.Header["alg"])
		}
		return publicKey, nil
	})

	if err != nil {
		if err.(*jwt.ValidationError).Errors == jwt.ValidationErrorExpired {
			return "Token has expired", nil
		}
		return "Invalid token", nil
	}

	if claims, ok := token.Claims.(jwt.MapClaims); ok && token.Valid {
		return claims, nil
	} else {
		return nil, fmt.Errorf("invalid token")
	}
}

